-- 外研社八上 wy8A s5 阅读灌库(junior_reading)· publisher=junior_fltrp · volume=wy8A · grade=8 · 6篇/每篇5题
-- 幂等:按(publisher,volume)先删后插。id/source_key 不预生成。Aaron 跑。
BEGIN;

DELETE FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy8A';

-- 6 篇
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U1', 'The books that have changed me', 'When I was young, I did not like reading at all. To me, books were boring, and I spent all my free time on games. But things have changed a lot since then.

Two years ago, my aunt gave me a thick story book for my birthday. It was about a young boy and his adventures in a strange land. At first I put it on the shelf and forgot about it. One rainy afternoon, with nothing to do, I opened it. I could not stop. I read for three hours without moving.

Since that day, I have read more than a hundred books. I have travelled to faraway places, met brave heroes, and lived a thousand lives, all inside my own room. Books have taught me about history, science, and people''s hearts. They have made me a kinder and wiser person.

My friends often ask about my love of reading. I always give them the same answer. ''A good book is a good friend,'' I say. ''It has never let me down.''

I have not finished my journey yet. So many wonderful books are still waiting for me. And I have made myself a promise: I will keep reading for the rest of my life.', '书籍带来的改变(现在完成时·经历)', 207, 2, '[{"q": "How did the writer feel about reading when he was young?", "answer": "B", "options": ["He loved reading story books.", "He thought reading was boring.", "He read for three hours every day.", "He had no free time at all."], "explanation": "开头''I did not like reading at all. To me, books were boring''。"}, {"q": "What has the writer done since he got the book from his aunt?", "answer": "C", "options": ["He has stopped playing games forever.", "He has written a hundred books.", "He has read more than a hundred books.", "He has sold his story books."], "explanation": "''Since that day, I have read more than a hundred books''。"}, {"q": "What is the main idea of the passage?", "answer": "C", "options": ["Games are better than books.", "Aunts always give the best gifts.", "Reading has changed the writer''s life for the better.", "The writer wants to be a writer."], "explanation": "全文写阅读如何改变了''我'',使''我''更善良更有智慧。"}, {"q": "We can learn from the passage that the writer ____.", "answer": "A", "options": ["will go on reading in the future", "dislikes his aunt''s gift now", "reads only on rainy days", "has finished reading every book"], "explanation": "结尾''I will keep reading for the rest of my life''可推断他会继续阅读。"}, {"q": "In the passage, the sentence ''It has never let me down'' means a good book ____.", "answer": "A", "options": ["has never made him disappointed", "has never fallen on the floor", "is never heavy to carry", "has never been opened"], "explanation": "let sb down=让某人失望;此处指好书从未让''我''失望。"}]'::jsonb, '[{"word": "adventure", "cn": "冒险经历"}, {"word": "faraway", "cn": "遥远的"}, {"word": "wiser", "cn": "更有智慧的"}, {"word": "journey", "cn": "旅程"}, {"word": "hero", "cn": "英雄"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U2', 'The old man and the bench', 'On a busy street stood a small shop. Outside it sat an old wooden bench. The bench has welcomed tired people for many years. Old men rested there in the sun. Children sat on it to eat their sweets. Mothers stopped to catch their breath. Everyone loved that friendly corner.

The shopkeeper, Mr Lang, grew selfish over time. ''This bench is mine,'' he said one morning. ''Why should strangers use it for free?'' He painted a hard sign and nailed it to the wall: NO SITTING. From that day, no one stopped at his corner any more.

Something strange happened. The street outside turned cold and quiet. Fewer people came to buy his bread. Mr Lang sat alone behind his counter, day after day, and his heart grew as hard as stone.

One winter evening, he saw a small girl by the wall, too tired and cold to walk home. For the first time in years, his heart softened. He carried the bench back out and gently helped her sit.

''Rest here, child,'' he said softly. ''This bench has always been for everyone.''

Slowly the people returned, and warm talk filled the corner again. Mr Lang has kept the bench outside since that night, and he has not felt lonely for a single day.', '分享与善良(现在完成时·since/for)·改写王尔德《自私的巨人》', 214, 2, '[{"q": "Why did people love the corner outside Mr Lang''s shop at first?", "answer": "B", "options": ["Because Mr Lang gave them free bread.", "Because the bench there welcomed tired people.", "Because the shop sold cheap sweets.", "Because the street was always warm."], "explanation": "开头长凳多年欢迎疲惫的人,大家喜欢那个友好的角落。"}, {"q": "What happened after Mr Lang put up the ''NO SITTING'' sign?", "answer": "D", "options": ["More people came to rest.", "The bench became newer.", "His bread sold better.", "No one stopped at his corner any more."], "explanation": "''From that day, no one stopped at his corner any more''。"}, {"q": "What does the story mainly tell us?", "answer": "C", "options": ["A shop should sell good bread.", "Old benches are hard to keep.", "Sharing and kindness bring warmth back to life.", "Winter is a cold and lonely season."], "explanation": "全文借长凳讲分享与善良让温暖回归。"}, {"q": "From ''his heart softened'', we can infer that Mr Lang ____.", "answer": "A", "options": ["began to feel kind again", "became ill that winter", "wanted to sell the bench", "was angry at the girl"], "explanation": "心软了→他重新变得善良,故carried the bench back。"}, {"q": "The underlined word ''selfish'' in the passage means ____.", "answer": "B", "options": ["kind and warm to everyone", "caring only about oneself", "tired and weak", "poor and hungry"], "explanation": "由他不许他人用长凳可推断selfish=只顾自己、自私。"}]'::jsonb, '[{"word": "bench", "cn": "长凳"}, {"word": "shopkeeper", "cn": "店主"}, {"word": "selfish", "cn": "自私的"}, {"word": "nailed", "cn": "钉(nail的过去式)"}, {"word": "counter", "cn": "柜台"}, {"word": "softened", "cn": "变软,软化"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U3', 'The boy who loved to invent', 'Ben was a curious boy who loved to make things. While other children enjoyed playing outside, he preferred sitting at his desk with wires, boxes, and old clocks. He wanted to build something useful, not just toys.

His grandmother lived with them. Her legs were weak, and carrying water up the stairs to her plants on the roof was hard for her. Ben decided to help. He planned to build a small machine to take the water up for her.

His first try failed. The machine dropped all the water on the floor. His second try failed too. It moved too fast and broke a pot. Ben''s friends told him to give up, but he refused to stop. ''Every failure teaches me something new,'' he said. He kept changing his design and testing it again and again.

After twenty tries, the little machine finally worked. It carried a cup of water slowly and safely up to the roof. His grandmother clapped her hands and started to cry with joy. Soon many neighbours came to see the little machine work, and everyone smiled at the boy with a proud look.

That evening, Ben wrote in his notebook: ''To invent is to fail, and to fail is to learn.'' He has never stopped inventing since then. He hopes to build machines to help many more people one day.', '发明与坚持(不定式/动名词作宾语)', 227, 2, '[{"q": "What did Ben prefer to do in his free time?", "answer": "B", "options": ["Playing outside with other children.", "Sitting at his desk making things.", "Watering the plants on the roof.", "Reading old story books."], "explanation": "''he preferred sitting at his desk with wires, boxes, and old clocks''。"}, {"q": "Why did Ben want to build the machine?", "answer": "C", "options": ["To win a school prize.", "To sell it for money.", "To help his grandmother take water up the stairs.", "To play a new game."], "explanation": "祖母腿脚弱,上楼浇花难,Ben decided to help,build a machine to take the water up。"}, {"q": "What is the best title''s idea of the passage?", "answer": "C", "options": ["Machines are dangerous to build.", "Grandmothers need a lot of help.", "Never give up, and failure can lead to success.", "Toys are better than real machines."], "explanation": "全文借Ben多次失败仍坚持,最终成功,讲永不放弃。"}, {"q": "What can we learn about Ben from the passage?", "answer": "A", "options": ["He is patient and never gives up easily.", "He hates making mistakes.", "He gave up after the second try.", "He only builds toys for fun."], "explanation": "''refused to stop'',''kept changing his design'',''twenty tries''可推断他有耐心、不放弃。"}, {"q": "In ''his second try failed too'', the word ''failed'' means ____.", "answer": "A", "options": ["did not work or succeed", "became very fast", "made a loud sound", "cost too much money"], "explanation": "由机器把水洒了、打破花盆可知failed=没成功、失败。"}]'::jsonb, '[{"word": "curious", "cn": "好奇的"}, {"word": "wires", "cn": "电线(wire的复数)"}, {"word": "design", "cn": "设计(方案)"}, {"word": "failure", "cn": "失败"}, {"word": "clapped", "cn": "鼓掌(clap的过去式)"}, {"word": "invent", "cn": "发明"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U4', 'Great-grandmother''s diary', 'In the year 2095, a girl named Mia learned everything at home. A smooth glass screen on her wall taught her every subject. It told her to sit up straight, asked her to answer questions, and made her repeat words until she got them right. Mia never left her room. She had no classmates, only the calm voice of the screen. Every morning looked just like the one before, quiet and grey and always the same.

One afternoon, while cleaning a dusty cupboard, Mia found a small book with soft yellow pages. Someone wrote inside it by hand. It was her great-grandmother''s diary, almost eighty years old.

Mia began to read. Her great-grandmother wrote about a place called ''school'', a real building full of children. They sat together in one room. They shared lunch, laughed at jokes, and ran in the yard at noon. A kind teacher helped them with their questions and told them wonderful stories. Sometimes they argued, sometimes they helped each other, but they were never alone.

Mia held the little diary close to her chest. She looked around her quiet, empty room and felt something new and cold inside her. The screen asked her to start the next lesson, but she did not move.

''They had so much fun together,'' she said softly. ''I only want a friend to sit beside me too. I want my school to make me feel that way one day.''', '科技与共同学习(不定式作宾补)·改写阿西莫夫《他们曾拥有的乐趣》', 241, 2, '[{"q": "How did Mia learn her lessons at home?", "answer": "B", "options": ["A kind teacher came to her house.", "A glass screen on the wall taught her.", "She read her great-grandmother''s diary.", "She studied with her classmates."], "explanation": "''A smooth glass screen on her wall taught her every subject''。"}, {"q": "What did Mia find in the dusty cupboard?", "answer": "C", "options": ["A new glass screen.", "A box of old toys.", "Her great-grandmother''s handwritten diary.", "A letter from her teacher."], "explanation": "''Mia found a small book... her great-grandmother''s diary''。"}, {"q": "What does the passage mainly want to tell us?", "answer": "D", "options": ["Screens are the best way to learn.", "Old diaries are hard to read.", "Children should stay at home to study.", "Learning together with others brings real joy."], "explanation": "全文对比孤独的屏幕学习与旧日共同学习的乐趣,点明与人共学的快乐。"}, {"q": "How did Mia most probably feel after reading the diary?", "answer": "A", "options": ["Lonely, and wishing for friends to learn with.", "Happy with her screen lessons.", "Angry at her great-grandmother.", "Afraid of the old school."], "explanation": "她感到又新又冷的东西、想要一个朋友,可推断她感到孤独、渴望同伴。"}, {"q": "In the passage, ''classmates'' means ____.", "answer": "B", "options": ["teachers who give lessons", "students who study in the same class", "books on the shelf", "rooms in a school"], "explanation": "由''no classmates, only the... screen''与后文一屋子孩子可推断=同班同学。"}]'::jsonb, '[{"word": "screen", "cn": "屏幕"}, {"word": "subject", "cn": "学科"}, {"word": "classmates", "cn": "同学"}, {"word": "cupboard", "cn": "橱柜"}, {"word": "diary", "cn": "日记"}, {"word": "great-grandmother", "cn": "曾祖母"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U5', 'Small rules, big reasons', 'Every day we follow many small rules, and each one has a good reason behind it. We may not always notice them, but they keep our lives safe and pleasant.

Think about a simple car ride. We put on a seat belt to protect ourselves if the car stops suddenly. The driver slows down near a school to keep the children safe. People wait for the green light to cross the road without danger. These rules do not exist to trouble us. They exist to save lives. We keep to the right on busy stairs, so no one runs into another person. We wash our hands before meals to stay clean and well.

Good manners work in the same quiet way. We speak softly in a library to let others read in peace. We throw rubbish in the bin to keep our streets clean. We line up at the shop to make things fair for everyone. In order to live together happily, we all give up a little of our own freedom.

Honesty is a rule of the heart. We tell the truth to keep our friends'' trust. We return what we borrow to show respect. If someone breaks these rules, he may win something small today, but he will lose something far greater tomorrow.

So the next time you follow a rule, stop to think about its reason. Behind every good rule stands a wish: to protect, to share, and to care.', '规则与文明(不定式表目的)', 243, 2, '[{"q": "Why do we put on a seat belt in a car?", "answer": "A", "options": ["To protect ourselves if the car stops suddenly.", "To make the car go faster.", "To keep the car clean.", "To follow the driver''s order."], "explanation": "''We put on a seat belt to protect ourselves if the car stops suddenly''。"}, {"q": "According to the passage, why do we speak softly in a library?", "answer": "C", "options": ["To save our own time.", "To make the room warm.", "To let others read in peace.", "To keep the books clean."], "explanation": "''We speak softly in a library to let others read in peace''。"}, {"q": "What is the main idea of the passage?", "answer": "B", "options": ["Rules make our lives hard and boring.", "Every rule exists for a good reason.", "Only drivers need to follow rules.", "Honesty is the only rule that matters."], "explanation": "全文说明每条小规则背后都有好理由——保护、分享、关爱。"}, {"q": "The writer would probably agree that ____.", "answer": "A", "options": ["following rules helps everyone live better together", "rules take away all our freedom", "only children need good manners", "breaking rules brings great rewards"], "explanation": "全文肯定规则的意义,可推断作者认为守规则使大家更好地共同生活。"}, {"q": "In the passage, the word ''honesty'' is closest in meaning to ____.", "answer": "A", "options": ["telling the truth and keeping trust", "working very fast", "saving a lot of money", "staying quiet in public"], "explanation": "由''tell the truth'',''keep trust''可推断honesty=诚实。"}]'::jsonb, '[{"word": "seat belt", "cn": "安全带"}, {"word": "rubbish", "cn": "垃圾"}, {"word": "bin", "cn": "垃圾桶"}, {"word": "honesty", "cn": "诚实"}, {"word": "trust", "cn": "信任"}, {"word": "freedom", "cn": "自由"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U6', 'The night of the flood', 'It was raining hard on the night everything changed. In a small mountain village, most people were sleeping quietly in their beds. Lily, a fifteen-year-old girl, was still awake. She was reading by the window while the storm grew louder and louder outside.

Around midnight, she heard a strange, deep sound. She looked out. A wall of water was rushing down the mountain towards the village. The river rose too fast. While the others were dreaming, the flood was coming.

Lily did not wait. She ran into the street, shouting and knocking on every door. ''Wake up! The water is coming! Run to the hill!'' Doors opened one by one. Sleepy families grabbed their children and hurried up the slope. Lily kept running from house to house while the cold water was already touching her feet.

By the time the flood reached the village, everyone was standing safely on the high ground. They watched their homes disappear under the brown water, but no one lost a life. The rain kept falling for hours, but the whole village was safe. Parents held their children close, and the old people thanked the brave girl again and again.

That night, a young girl became the hero of her village. When people later asked her about her fear, she only smiled. ''I was too busy to be afraid,'' she said. ''Everyone was in danger, so I just ran.''

The villagers have never forgotten her. Every year, on that day, they still tell her brave story.', '灾难与勇气(过去进行时)', 253, 2, '[{"q": "What was Lily doing around midnight when others were sleeping?", "answer": "B", "options": ["She was already asleep in bed.", "She was reading by the window.", "She was running up the hill.", "She was closing every door."], "explanation": "''She was reading by the window while the storm grew louder''。"}, {"q": "How did Lily warn the villagers?", "answer": "C", "options": ["She rang a big bell on the hill.", "She called them on the phone.", "She ran in the street, shouting and knocking on doors.", "She turned on all the lights."], "explanation": "''She ran into the street, shouting and knocking on every door''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["A terrible rainstorm in summer.", "How to build a house on high ground.", "A brave girl who saved her village from a flood.", "Why rivers rise in the mountains."], "explanation": "全文讲Lily在洪水之夜勇敢叫醒全村,救了大家。"}, {"q": "We can infer from Lily''s words that she ____.", "answer": "A", "options": ["cared more about others than about her own fear", "was not afraid of anything at all", "wanted people to praise her", "enjoyed running in the rain"], "explanation": "''too busy to be afraid'',''Everyone was in danger, so I just ran''可推断她把他人安危放在自己害怕之上。"}, {"q": "In the passage, ''flood'' means ____.", "answer": "A", "options": ["a great amount of water covering the land", "a strong cold wind", "a tall mountain", "a quiet river in summer"], "explanation": "由水从山上奔涌、淹没房屋可推断flood=洪水。"}]'::jsonb, '[{"word": "flood", "cn": "洪水"}, {"word": "rushing", "cn": "奔涌(rush的现在分词)"}, {"word": "slope", "cn": "斜坡"}, {"word": "grabbed", "cn": "抓住(grab的过去式)"}, {"word": "villager", "cn": "村民"}, {"word": "brave", "cn": "勇敢的"}]'::jsonb);

-- 断言
DO $$
DECLARE rn int; qbad int; orphan int; poll int;
BEGIN
  SELECT count(*) INTO rn FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy8A';
  SELECT count(*) INTO qbad FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy8A' AND jsonb_array_length(questions)<>5;
  SELECT count(*) INTO orphan FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy8A' AND unit IS NULL;
  SELECT count(*) INTO poll FROM public.junior_reading WHERE volume='wy8A' AND publisher<>'junior_fltrp';
  IF rn<>6 THEN RAISE EXCEPTION 'reading=% 期望6', rn; END IF;
  IF qbad<>0 THEN RAISE EXCEPTION '题数≠5的篇=%', qbad; END IF;
  IF orphan<>0 THEN RAISE EXCEPTION 'unit空=%', orphan; END IF;
  IF poll<>0 THEN RAISE EXCEPTION 'pep_polluted=%', poll; END IF;
  RAISE NOTICE 'OK: wy8A 阅读 % 篇', rn;
END $$;

COMMIT;